def busca_binaria(lista, elemento):
    if sorted(lista) != lista:
        raise ValueError('A lista deve estar ordenada.')
    esquerda = 0
    direita = len(lista) - 1
    while esquerda <= direita:
        meio = (esquerda + direita) // 2
        if lista[meio] == elemento:
            return meio
        elif lista[meio] < elemento:
            esquerda = meio + 1
        else:
            direita = meio - 1
